(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*18 + Math.cos(y*0.012-t*0.2)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.015-t*0.25)*18 + Math.sin(x*0.013+t*0.35)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.02-t*0.4)*10 + Math.cos(my*0.018+t*0.3)*7;
  const w2y = Math.cos(my*0.02+t*0.35)*10 + Math.sin(mx*0.016-t*0.28)*7;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.095, 2.1],
    [400+Math.cos(t*0.55+2)*85, 200+Math.sin(t*0.75+4)*65, 0.075, 1.8]
  ];
  let aS=0, iS1=0, iS2=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS1 += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    iS2 += Math.sin(d*f*0.5 - t*sp*0.4 + 3.0) * Math.cos(d*f*0.3 + t*sp*0.3);
  }
  const act=aS/8, inh1=iS1/8, inh2=iS2/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1)+Math.sin(sx*0.045+sy*0.005-t*0.9))/3;
  const hiBg = (Math.sin((sx+sy)*0.11+t*2.5)+Math.sin((sx-sy)*0.095-t*2)+Math.sin(sx*0.08+sy*0.13+t*1.8))*0.18;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = (Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.038+ang*4-t*1.2))*0.35;
  const sp2 = Math.sin(dist*0.06-ang*2+t*0.8)*Math.cos(dist*0.025+ang*5-t*1.6)*0.25;
  const spiral = sp1+sp2;
  const pulse = Math.sin(t*0.4)*0.15+Math.sin(t*0.67)*0.1;
  const rd = Math.tanh((act - inh1*0.6 - inh2*0.3 + bg*0.25 + spiral + pulse)*2.0);
  const cx1=Math.sin(sx*0.14)*Math.sin(sy*0.14), cx2=Math.sin((sx+sy)*0.09+t*0.7)*0.5;
  const cx3=Math.sin(sx*0.07-t*0.3)*Math.cos(sy*0.11+t*0.4)*0.3;
  const cell = Math.tanh((cx1+cx2+cx3)*1.3)*0.25;
  const edge = Math.abs(rd)>0.65?1.2:Math.abs(rd)>0.4?1.08:1.0;
  const glow = Math.max(0, Math.abs(rd)-0.5)*0.8;
  const blend = rd*0.65+cell*0.2+glow*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,88],[18,95,115],[25,148,135],[120,175,80],
    [210,195,60],[225,145,55],[215,90,55],[180,50,60],[120,25,55],
    [60,15,48],[20,10,45],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(rd*Math.PI)*0.18+glow*0.3;
  const breathe = 0.95+Math.sin(t*0.5)*0.05;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*breathe+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*breathe+glow*20)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*breathe+glow*15)|0)
  ];
}
